class FortranCoeffBackend(NumPyCoeffBackend):
    """implement the backend for 'Fortran'"""

    def coeff_new_array(self, size: int, dtype: str):
        return super().coeff_new_array(size=size, dtype=dtype)

    def coeff_from_numpy(
        self,
        coeff_like: Any,
        nparray: np.ndarray,
        size: int,
        dtype: str,
    ) -> None:
        return super().coeff_from_numpy(
            coeff_like=coeff_like,
            nparray=nparray,
            size=size,
            dtype=dtype,
        )

    def coeff_to_numpy(
        self, coeff_like: Any, size: int, dtype: str
    ) -> np.ndarray:
        return super().coeff_to_numpy(
            coeff_like=coeff_like, size=size, dtype=dtype
        )

    def coeff_linop(
        self,
        arr_r: Any,
        /,
        scal_a: float | None,
        arr_x: Any,
        scal_b: float | None,
        arr_y: Any,
        *,
        size: int,
        dtype: str,
        inplace: bool = False,
    ):
        return super().coeff_linop(
            arr_r,
            scal_a=scal_a,
            arr_x=arr_x,
            scal_b=scal_b,
            arr_y=arr_y,
            size=size,
            dtype=dtype,
            inplace=inplace,
        )


