class CuPyCoeffBackend(CoeffBackend):
    """implement the backend for 'CuPy'"""

    def coeff_new_array(self, size: int, dtype: str):
        match dtype:
            case "f32":
                return cp.zeros(size, dtype=cp.float32)
            case "f64":
                return cp.zeros(size, dtype=cp.float64)
            case "i32":
                return cp.zeros(size, dtype=cp.int32)
            case "i64":
                return cp.zeros(size, dtype=cp.int64)
            case _:
                raise ValueError(f"dtype {dtype} not understood")

    def coeff_from_numpy(
        self,
        coeff_like: Any,
        nparray: np.ndarray,
        size: int,
        dtype: str,
    ) -> None:
        if dtype in ("f32", "f64"):
            if nparray.dtype in [np.float32, np.float64]:
                coeff_like[:] = cp.asarray(nparray)
            else:
                raise ValueError(
                    f"Wrong input datatype {nparray.dtype} for dtype {dtype}."
                )
        elif dtype in ("i32", "i64"):
            if nparray.dtype in [np.int32, np.int64]:
                coeff_like[:] = cp.asarray(nparray)
            else:
                raise ValueError(
                    f"Wrong input datatype {nparray.dtype} for dtype {dtype}."
                )
        else:
            raise ValueError(f"dtype {dtype} not understood")

    def coeff_to_numpy(
        self, coeff_like: Any, size: int, dtype: str
    ) -> np.ndarray:
        match dtype:
            case "f32":
                return np.array(cp.asnumpy(coeff_like), dtype=np.float32)
            case "f64":
                return np.array(cp.asnumpy(coeff_like), dtype=np.float64)
            case "i32":
                return np.array(cp.asnumpy(coeff_like), dtype=np.int32)
            case "i64":
                return np.array(cp.asnumpy(coeff_like), dtype=np.int64)
            case _:
                raise ValueError(f"dtype {dtype} not understood")

    def coeff_linop(
        self,
        arr_r: Any,
        /,
        scal_a: float | None,
        arr_x: Any,
        scal_b: float | None,
        arr_y: Any,
        *,
        size: int,
        dtype: str,
        inplace: bool = False,
    ):
        match (inplace, scal_a):
            case (True, None):
                arr_r[:] += arr_x
            case (True, scal_a):
                arr_r[:] += scal_a * arr_x
            case (False, None):
                arr_r[:] = arr_x
            case (False, scal_a):
                arr_r[:] = scal_a * arr_x

        match (scal_b, arr_y):
            case (None, None):
                return
            case (None, arr_y):
                arr_r[:] += arr_y
            case (scal_b, None):
                arr_r[:] += scal_b
            case (scal_b, arr_y):
                arr_r[:] += scal_b * arr_y


