'''
FROM THE DOCS...

import pyopencl as cl

rng = np.random.default_rng()
a_np = rng.random(50000, dtype=np.float32)
b_np = rng.random(50000, dtype=np.float32)

ctx = cl.create_some_context()
queue = cl.CommandQueue(ctx)

mf = cl.mem_flags
a_g = cl.Buffer(ctx, mf.READ_ONLY | mf.COPY_HOST_PTR, hostbuf=a_np)
b_g = cl.Buffer(ctx, mf.READ_ONLY | mf.COPY_HOST_PTR, hostbuf=b_np)

prg = cl.Program(ctx, """
__kernel void sum(
    __global const float *a_g, __global const float *b_g, __global float *res_g)
{
  int gid = get_global_id(0);
  res_g[gid] = a_g[gid] + b_g[gid];
}
""").build()

res_g = cl.Buffer(ctx, mf.WRITE_ONLY, a_np.nbytes)
knl = prg.sum  # Use this Kernel object for repeated calls
knl(queue, a_np.shape, None, a_g, b_g, res_g)

res_np = np.empty_like(a_np)
cl.enqueue_copy(queue, res_np, res_g)
'''


class OpenClCoeffBackend(CoeffBackend):
    """implement the backend for 'OpenCl'"""

    def __init__(self, *args, **kwargs):
        super().__init__(self, *args, **kwargs)

        self._cl_cntxt = cl.create_some_context()
        self._cl_queue = cl.CommandQueue(self._cl_cntxt)

        self._cl_mflag = cl.mem_flags

    def coeff_new_array(self, size: int, dtype: str):
        try:
            read_write = self._cl_mflag.READ_WRITE

            floats = cl.Buffer(
                self._cl_cntxt,
                read_write,
                size=8 * size,  # size in bytes
            )
        except cl.Error as e:
            warnings.warn("Failed to create OpenCL buffer: {}".format(str(e)))
            return (None, None)
        return floats

    def coeff_from_numpy(
        self,
        coeff_like: Any,
        nparray: np.ndarray,
        size: int,
        dtype: str,
    ) -> None:
        raise NotImplementedError()

    def coeff_to_numpy(
        self, coeff_like: Any, size: int, dtype: str
    ) -> np.ndarray:
        raise NotImplementedError()

    def coeff_linop(
        self,
        arr_r: Any,
        /,
        scal_a: float | None,
        arr_x: Any,
        scal_b: float | None,
        arr_y: Any,
        *,
        size: int,
        dtype: str,
        inplace: bool = False,
    ):
        raise NotImplementedError()


